S = "Hakeem Force Academy"
QS = [
(S, "What does LOC stand for in the context of Kashmir?", ["Line of Control", "Line of Conflict", "Limit of Control", "Line of Command"], 0, "LOC stands for Line of Control, the de facto border dividing Indian-administered and Pakistani-administered Kashmir. It came out of the ceasefire line of 1948 and was renamed after the Simla Agreement of 1972.", "Pakistan and India both claim the whole of Kashmir, so the LOC is not an internationally recognised border.", [48, 984]),
(S, "Approximately how many litres of blood does an average adult human body contain?", ["About 5 litres", "About 2 litres", "About 8 litres", "About 10 litres"], 0, "An average adult has roughly 4.5 to 5.5 litres of blood, usually given as about 5 litres. This is around 7 percent of body weight.", "Women usually have slightly less blood volume than men.", [94]),
(S, "Who is the author of the book India, My Love?", ["Dominique Lapierre", "Khushwant Singh", "Salman Rushdie", "Arundhati Roy"], 0, "India, My Love is a book by the French author Dominique Lapierre about his travels in India. The French title is India Mon Amour.", "Lapierre also wrote City of Joy and, with Larry Collins, Freedom at Midnight; a different book called India My Love: A Spiritual Journey also exists.", [81]),
(S, "On which date was the first official Test match in cricket history started?", ["15 March 1877", "1 January 1900", "15 August 1877", "12 June 1890"], 0, "The first Test match, Australia against England, began on 15 March 1877 at the Melbourne Cricket Ground. Australia won it by 45 runs.", "Pakistan played its first Test in 1952 against India at Delhi.", [756]),
(S, "What is a matrix called in which all the entries are zero?", ["Zero (null) matrix", "Identity matrix", "Scalar matrix", "Diagonal matrix"], 0, "A matrix whose every entry is zero is called a zero matrix or null matrix. It is the additive identity for matrices of the same order.", "Adding a zero matrix to any matrix of the same order leaves it unchanged.", [830]),
(S, "In statistics, what is the difference between the maximum value and the minimum value of a data set called?", ["Range", "Mean", "Median", "Mode"], 0, "Range is the largest value minus the smallest value in the data. For example, in 3, 7, 12 the range is 12 - 3 = 9.", "Range is the simplest measure of how spread out data is.", [948]),
(S, "What does the idiom 'call it a day' mean?", ["Stop working for the day", "Start a new job", "Phone someone every day", "Work all day long"], 0, "To call it a day means to stop what you are doing and finish for the time being. It is used when one has done enough work.", "A similar idiom is 'call it a night'.", [835]),
(S, "What is an interjection in English grammar?", ["A word that expresses sudden emotion, such as Wow or Alas", "A word that names a person or place", "A word that describes a noun", "A word that joins two sentences"], 0, "An interjection is a word or short phrase that shows sudden feeling like surprise, joy or pain. Examples are Oh, Hurrah and Alas.", "An interjection is usually followed by an exclamation mark.", [837]),
(S, "In which sport did Pakistan win its first Olympic gold medal?", ["Hockey", "Cricket", "Squash", "Wrestling"], 0, "Pakistan won its first Olympic gold in field hockey at the 1960 Rome Olympics. It beat India 1-0 in the final.", "Pakistan has won three Olympic hockey golds: 1960, 1968 and 1984.", [766]),
(S, "How many member states does the Organisation of Islamic Cooperation (OIC) have?", ["56", "48", "57", "60"], 2, "The OIC has 57 member states, as stated by the organisation itself. It is the second largest intergovernmental body after the United Nations.", "The OIC headquarters is in Jeddah, Saudi Arabia.", [47, 1035]),
(S, "A man walks 5 metres north, turns left and walks 50 metres, then turns right. In which direction is he now heading?", ["West", "East", "South", "North"], 3, "Facing north, a left turn makes him face west. Turning right from west makes him face north again.", "A left turn is 90 degrees anticlockwise and a right turn is 90 degrees clockwise.", [620]),
(S, "What is the commonly stated range of Pakistan's Nasr (Hatf-IX) short-range ballistic missile?", ["70 km", "350 km", "180 km", "1,000 km"], 0, "Nasr is a short-range, nuclear-capable missile with a reported range of 60 to 70 km, with the upgraded version given as 70 km. It is meant as a battlefield weapon.", "Early reports gave 60 km, so sources differ depending on the variant.", [119, 1148]),
(S, "If the 12th day of a month is Monday, which day is the 25th of that month?", ["Saturday", "Monday", "Sunday", "Tuesday"], 2, "From the 12th to the 25th is 13 days. 13 divided by 7 leaves remainder 6, so Monday plus 6 days is Sunday.", "Any two dates 7 days apart fall on the same weekday.", [603]),
(S, "If the 3rd day of a month is Monday, which day is the 15th of that month?", ["Friday", "Sunday", "Saturday", "Monday"], 2, "From the 3rd to the 15th is 12 days. 12 divided by 7 leaves remainder 5, so Monday plus 5 days is Saturday.", "The 10th and 17th of that month are also Mondays.", [607]),
(S, "Who built the Mohabbat Khan Mosque in Peshawar?", ["Nawab Mohabbat Khan, Mughal governor of Peshawar", "Emperor Aurangzeb", "Sher Shah Suri", "Emperor Akbar"], 0, "The mosque was built around 1630 by Nawab Mohabbat Khan, the Mughal governor of Peshawar under Emperor Shah Jahan.", "It is one of the best known Mughal-era mosques of Peshawar.", [1313]),
(S, "On which date was the Quit India resolution passed by the Indian National Congress in 1942?", ["8 August 1942", "23 March 1942", "14 August 1942", "9 August 1945"], 0, "The Quit India resolution was passed at Bombay on 8 August 1942 and the movement began the next day. It demanded an end to British rule in India.", "Gandhi gave the call Do or Die during this movement.", [758]),
(S, "A car moves at 60 km/h and a train moves at twice the speed of the car. How far does the train travel in 30 minutes?", ["120 km", "30 km", "90 km", "60 km"], 3, "Train speed is 2 x 60 = 120 km/h. In 30 minutes (half an hour) it travels 120 x 0.5 = 60 km.", "Distance equals speed multiplied by time.", [346]),
(S, "What is 6 multiplied by 5?", ["36", "30", "35", "25"], 1, "6 x 5 means five sixes: 6 + 6 + 6 + 6 + 6 = 30.", "The multiplication table of 6 is 6, 12, 18, 24, 30.", [861]),
]
